# 注册 LxPlayerActivity 到 AndroidManifest.xml
MANIFEST="app/src/main/AndroidManifest.xml"
if ! grep -q "LxPlayerActivity" "$MANIFEST"; then
    python3 << 'PYEOF2'
manifest = "app/src/main/AndroidManifest.xml"
with open(manifest, 'r', encoding='utf-8') as f:
    c = f.read()
old = '<activity android:name=".ui.activity.LxSourceSettingsActivity"'
new = old + ' />\n        <activity android:name=".ui.activity.LxPlayerActivity"'
if old in c and "LxPlayerActivity" not in c:
    c = c.replace(old, new)
    with open(manifest, 'w', encoding='utf-8') as f:
        f.write(c)
    print("LxPlayerActivity 已注册到 Manifest")
# 注册通知 Receiver
with open(manifest, 'r', encoding='utf-8') as f:
    c2 = f.read()
receiver_tag = '<receiver android:name=".ui.activity.LxNotificationReceiver"'
if receiver_tag not in c2:
    c2 = c2.replace('</application>', '        ' + receiver_tag + ' android:exported="false">\n            <intent-filter>\n                <action android:name="com.github.tvbox.osc.lx.ACTION_TOGGLE" />\n                <action android:name="com.github.tvbox.osc.lx.ACTION_NEXT" />\n                <action android:name="com.github.tvbox.osc.lx.ACTION_PREV" />\n                <action android:name="com.github.tvbox.osc.lx.ACTION_CLOSE" />\n            </intent-filter>\n        </receiver>\n    </application>')
    with open(manifest, 'w', encoding='utf-8') as f:
        f.write(c2)
    print("LxNotificationReceiver 已注册")
PYEOF2
fi

echo "=== 播放器 Spotify 风格完成 ==="
